export const newArticleContent: Record<string, ArticleSection[]> = {
  "superbuy-shipping-calculator": [
    s("What the Superbuy shipping calculator can tell you",
      "The Superbuy shipping calculator is a planning tool, not a binding quote. It combines a destination, an estimated parcel weight and dimensions, and currently available delivery lines to produce a comparison. That comparison is useful before buying because it exposes the scale of international delivery, but it cannot know the final carton, the warehouse-confirmed item attributes or the exact line that will still be available when you submit the parcel.",
      "Use the result as a dated scenario. Record the destination, currency, weight, three external dimensions and calculation date next to the estimate. If any of those inputs changes, create a new scenario instead of overwriting the old one. This makes the sheet honest about uncertainty and lets you see whether a later difference came from better measurements, a different route, packaging choices or a tariff update."),
    s("Separate actual weight from volumetric weight",
      "Actual weight is the value shown by a scale. Volumetric weight converts the space occupied by a parcel into a billable weight. Superbuy’s current international shipping estimator explains that most air cargo examples use length × width × height in centimetres divided by 6,000. A 60 × 40 × 30 cm carton therefore has 72,000 cubic centimetres and an example volumetric weight of 12 kg, even when the contents weigh less.",
      "Do not treat 6,000 as a universal divisor. Individual lines can publish a different divisor, rounding rule, minimum charge or method for irregular parcels. The applicable rule is the one displayed for the line when you compare it. Save both actual and volumetric weight, then note which value the line uses as chargeable weight. This is especially important for shoes, padded coats, plush items and products kept in large retail boxes."),
    s("Build three estimates instead of one precise-looking number",
      "The first estimate belongs at product-research stage. Use a broad range based on plausible packed weight and size, and mark every assumption. The second estimate belongs after warehouse arrival, when item weights, photos and dimensions provide better inputs. The third is the live parcel quote after you select the actual group of items, destination and packaging requests. Each stage should become more accurate without pretending the earlier stage was a promise.",
      "Keep product cost, Chinese domestic delivery, optional product services and international shipping in separate columns. A cheap product can still be bulky, while an expensive compact product can ship efficiently. Mixing these costs into one early total makes it impossible to see why a budget changed. A clear sheet preserves the calculator result and the evidence behind it rather than presenting a single unexplained ‘cost per kilogram’."),
    s("Measure the parcel scenario consistently",
      "Always enter outside parcel dimensions, not only the dimensions of the item. Protective material, a shoe box, empty space and the final carton all affect the space carried. Before warehouse data exists, test a conservative carton and a compact carton. After arrival, compare the stored item measurements and ask whether package removal or another packing service could safely change the final volume.",
      "Use the same units throughout the sheet and label them. Confusing grams with kilograms or inches with centimetres can create an estimate that looks plausible but is unusable. Round upward when building a budget buffer, but preserve the unrounded source measurement. The goal is to avoid false precision while still making every assumption reproducible."),
    s("Compare eligible lines on more than headline price",
      "A route comparison should use the same parcel contents, destination, weight, dimensions and date. For each eligible line, record the displayed price, delivery-time range, chargeable-weight method, tracking level, insurance option, parcel limits and item restrictions. A lower headline price may have a larger billing increment, less suitable compensation terms or restrictions that matter more than the initial saving.",
      "Superbuy states that international delivery is performed by third-party logistics providers and that customs processing, restrictions and delivery timing cannot be fully controlled. Treat time ranges as estimates. Do not convert a fast result from one shipment into a guarantee for the next. Reopen the line details at submission because carrier capacity and route rules can change between research and payment."),
    s("Test consolidation and splitting as competing scenarios",
      "Free consolidation can reduce repeated base charges and unnecessary packaging, but it can also create a larger volumetric parcel or combine an unrestricted item with one that narrows the route list. Calculate at least two scenarios: the intended combined parcel and a sensible split based on volume, fragility or restrictions. Compare the full price and available lines, not only the number of parcels.",
      "Document why items belong together. Clothing may compress well; a boxed collectible may need shape protection; batteries or liquids may affect eligibility. If removing a box lowers volume, record the trade-off in protection and resale or collector value. The calculator supports the decision only when the parcel groups reflect how the items can actually travel."),
    s("Understand deposit and final reconciliation",
      "Superbuy’s current shopping-agent guide says the international shipping deposit is calculated from estimated weight, selected shipping method and destination. The final fee is based on the package size and weight verified by the shipping company. A difference may be returned to the account after shipment; the current fee page also notes that an underpayment can be collected. Preserve the deposit and final charge as separate values.",
      "A changed final charge is not automatically an error. It may reflect a different carton, chargeable weight, rounding unit or verified carrier data. Compare the saved inputs with the parcel record before contacting support. If something remains unexplained, provide the estimate date, line, stated measurements, deposit and final adjustment so the question can be checked against one identifiable parcel."),
    s("Add taxes and currency movement outside the freight formula",
      "The freight calculator does not remove destination customs, VAT, duty, clearance charges or card and currency-conversion effects. Keep a destination-tax reserve separate from the transport estimate and verify the current official customs guidance for the receiving country. Never assume that a route label or another buyer’s experience guarantees tax-free delivery.",
      "Also record the quote currency and the exchange rate used for your personal budget. A rate change can alter the card total even when the yuan freight charge is unchanged. Separating route price, conversion and import charges prevents a normal currency movement from being mistaken for a shipping-calculator failure."),
    s("A repeatable pre-submission calculator workflow",
      "Start with the destination and a realistic packed range. Enter actual and external dimensions, compare all eligible routes, open the conditions for the strongest candidates and save the result with a date. After warehouse arrival, replace assumptions with recorded item data, close outstanding QC decisions, test combined and split groups, and review packaging services before requesting the final quote.",
      "Immediately before payment, confirm the address, phone number, parcel contents, restricted attributes, declaration details, chargeable-weight rule, insurance and current line conditions. After delivery, add the final charge, adjustment, observed time and packaging outcome to the sheet. That history improves the next estimate without turning one parcel into a universal tariff."),
    s("Calculator worksheet fields that prevent false precision",
      "A reusable worksheet should contain input status, source and confidence as well as the number itself. Mark weight as seller estimate, warehouse measurement or packed verification. Mark dimensions as product, retail box or external parcel. Beside the route, save its billing unit, volumetric rule, restriction result and quote time. These labels stop unlike numbers from being compared as if they described the same object.",
      "Add three budget outputs: likely freight, contingency reserve and costs excluded from freight. The excluded column should name currency conversion and possible destination import charges. When the live parcel quote arrives, lock the scenario rather than editing it retroactively. A later route check becomes a new row. This audit trail makes calculator use transparent to another reader and gives you a defensible explanation when the final settlement differs."),
  ],

  "superbuy-tariffs-customs-vat": [
    s("Treat tariffs as a destination decision",
      "Superbuy tariffs are not a single platform percentage. Import VAT, customs duty, excise duty, clearance charges and carrier handling depend on the destination, the type and origin of the goods, the declared value and the rules in force when the parcel arrives. Superbuy’s fee structure states that destination-country customs charges are borne by the recipient. A spreadsheet should therefore hold a separate customs plan for each parcel.",
      "Begin with the official customs authority for the receiving country, not a forum screenshot or a seller promise. Record the page title, access date, currency, value threshold and product classification assumptions. Rules change, and a threshold may apply to the entire consignment rather than each item. A dated source note is more useful than a permanent ‘tax-free’ label."),
    s("Separate VAT, customs duty and handling charges",
      "VAT is a consumption tax calculated under destination rules. Customs duty is commonly tied to classification, origin and value. Excise duty applies to specific goods. A postal operator or courier may also charge for presenting the parcel to customs or collecting tax. These are different costs, even when the recipient receives one combined payment notice.",
      "Create separate budget lines for expected VAT, possible duty and carrier or clearance fees. Mark the calculation basis for each. If a route includes a tax-related service, read the live route terms and identify exactly what is included, rather than assuming every possible import cost has been prepaid. Keep the seller invoice and parcel declaration available for comparison."),
    s("Use the whole consignment value correctly",
      "Customs rules often evaluate a shipment as one consignment. Combining several purchases can change the value band even when every item is individually inexpensive. It can also change the parcel description, weight and route. Before consolidating, compare the customs consequences of one combined parcel with a reasonable split, while respecting rules against artificial undervaluation or misleading descriptions.",
      "The customs value may include more than the item price. Depending on the jurisdiction, postage, packaging, insurance and duty can form part of a VAT or duty base. Use the destination authority’s formula. Keep product cost and freight separate in the shopping sheet, then bring the required elements into the customs worksheet only according to the applicable rule."),
    s("Describe and classify goods honestly",
      "A useful declaration identifies the actual goods in plain language, quantity and value. Vague descriptions such as ‘gift’ or ‘sample’ do not make a commercial purchase exempt, and an incorrect description can delay clearance. Product categories can have different duty rates or restrictions, so the correct classification matters more than a broad label such as clothing or accessory.",
      "Preserve the order record, payment evidence and product description. If the item is difficult to classify, use the destination tariff database or request professional advice. This site cannot determine a legal commodity code from a product photo. The spreadsheet should flag the uncertainty and the official source that still needs to be checked."),
    s("Do not use gift relief for purchases",
      "Gift relief normally has strict conditions involving a private sender, a private recipient, occasional transfer and no payment by the recipient. Buying an item for yourself or purchasing an item to send as a present does not automatically make the import a customs gift. Marking a paid order as a gift can create an inaccurate declaration.",
      "Keep commercial purchases recorded as purchases and use the destination’s rules for bought goods. If another person genuinely sends a gift, review the separate official gift guidance and its value and quantity limits. Treat excise products and restricted goods as special cases requiring their own review."),
    s("Understand what a delivery line can and cannot promise",
      "Some route names mention tax or duty handling, but the label alone is not a complete contract. Open the current line details and record eligible destinations, product limits, declared-value rules, compensation terms and the stated tax process. If the wording is unclear, ask support before submission and save the answer with the quote date.",
      "No spreadsheet can guarantee that customs will not inspect, reclassify, delay or charge a parcel. Superbuy’s guide explicitly describes customs, confiscation, taxes, damage and delay as possible international-shipping risks outside full platform control. Plan a time and money buffer and avoid deadline-sensitive purchases that cannot tolerate clearance uncertainty."),
    s("Build a country verification checklist",
      "For every destination, check the customs authority, current VAT or sales-tax treatment, duty threshold, tariff database, prohibited and restricted goods, personal-import limits and courier collection process. Note whether the rule differs between regions of the same country. Northern Ireland and Great Britain, for example, can follow different customs treatments in some circumstances.",
      "Date every result. If the parcel is submitted weeks later, recheck the key threshold and route terms. An old calculation should remain in history but lose its ‘current’ status. This approach lets an SEO article be useful without freezing changing law into a permanent promise."),
    s("Plan for evidence and payment on arrival",
      "Keep the invoice, order screenshot, payment record, parcel number, declared description and freight amount together. A courier may contact the recipient for documents or payment before delivery. Use accurate contact details and monitor tracking so a time-limited notice is not missed. A parcel can be held or returned when requested charges or evidence are not supplied.",
      "If a charge appears wrong, follow the destination authority or courier process for review or refund. Do not solve the discrepancy by changing future declarations. Record the assessed value, tax type and outcome so the next budget can be improved from verified evidence."),
    s("A safe tariff budget is a range",
      "Calculate a low scenario using clearly applicable taxes, a central scenario with likely carrier charges, and a high scenario that includes possible duty and extra clearance. Show the assumptions beside each result. This is more useful than one exact figure that depends on an unverified classification or exchange rate.",
      "Before parcel submission, confirm the actual group value, honest description, route tax terms and official destination guidance. After delivery, reconcile the budget with the assessment. The purpose of tariff planning is readiness and compliance, not finding a phrase that promises a charge can be avoided."),
    s("Review restricted and prohibited goods before purchase",
      "Tax is only one border question. Food, medicine, cosmetics, batteries, liquids, plants, animal products, weapons and branded goods can face separate import or carrier restrictions. A product that can be purchased domestically may still be unsuitable for a selected international line or prohibited at the destination. Check both the customs authority and current delivery-line conditions before payment.",
      "Record the product attribute that triggered the review and the source used. If eligibility is unclear, do not disguise the product with a vague declaration. Ask the platform or a qualified customs adviser, and keep the item outside the planned parcel until the issue is resolved. A compliant plan protects the whole consignment from avoidable delay."),
    s("Reconcile the customs result after delivery",
      "When the parcel clears, save the declared value, customs value, tariff code if supplied, VAT, duty, excise, courier fee, exchange rate and assessment date. Compare those items with the budget rather than judging only the total. A difference may come from classification, a broader tax base, an official exchange rate or a handling charge.",
      "Use one assessment only as evidence for that shipment. The next parcel may contain different goods, arrive under revised rules or use another carrier. Reopen official guidance and rebuild the calculation. This feedback loop improves planning while avoiding the dangerous claim that a previous low charge establishes a reliable loophole."),
  ],

  "superbuy-expert-service": [
    s("When Superbuy Expert Service becomes relevant",
      "Superbuy’s shopping-agent guidance points users to Expert Service when the normal product search cannot find an item. The service is most relevant when a link cannot be parsed, the marketplace is not in the standard supported flow, the product needs manual specification, or the purchase requires communication that a simple option selector cannot capture. It is not a replacement for checking what you want.",
      "Before submitting anything, open the source page and write a precise purchase brief. Include the current URL, seller, product title, exact option, quantity, target price, domestic-delivery information and the question that requires manual help. Expert assistance can execute or clarify an instruction, but it cannot safely infer size, colour or model from a vague request."),
    s("Distinguish Expert Service from Shipping Expert",
      "The words are easy to confuse. Expert Service appears in Superbuy’s product-selection flow as a way to submit or find a product that normal search does not resolve. The current fee structure also lists a separate Shipping Expert purchasing category for special items such as pre-sales or limited editions, with its own percentage and minimum and maximum fees. Confirm which service the order page actually assigns.",
      "Record the displayed service name and fee before payment. Do not reuse an old percentage merely because the labels sound similar. A mainstream Taobao or 1688 purchase may fall under free standard purchasing, while a second-hand, unlisted-platform or special purchasing request can follow another rule. The live order breakdown is the controlling evidence."),
    s("Prepare a complete manual order brief",
      "A strong brief begins with one product, one intended variation and one fallback rule. Paste the link, copy the option text exactly, state colour and size separately, add quantity, and identify the thumbnail when a listing mixes unrelated items. If there is a maximum acceptable product price or domestic shipping amount, state it clearly and say whether the agent should pause if the seller changes it.",
      "For customisation, pre-sale or made-to-order goods, describe every required inscription, measurement, release date or seller confirmation. Avoid contradictory instructions across notes and messages. Save a local copy of the final brief and the time submitted so later replies can be matched with the version the agent received."),
    s("Use screenshots as supporting evidence, not the order itself",
      "Screenshots can show the selected thumbnail, option text or requested detail when a page is difficult to translate. They can also become stale. Keep the live URL as the primary destination and use the image to clarify one exact decision. Add visible annotations rather than expecting the agent to infer which part matters.",
      "If the seller replaces the listing or price, ask for confirmation before purchase. A screenshot of an earlier price does not force a seller to honour it. The spreadsheet row should move from ‘submitted’ to ‘agent confirmed’ only when the current response matches the intended product, option, cost and timing."),
    s("Review fees before authorising purchase",
      "Superbuy’s current fee page separates original product price, Chinese domestic shipping and purchasing service fee. It lists no purchasing fee for mainstream standard service, but separate rules for second-hand platforms, unlisted platforms and Shipping Expert. Optional detailed photos, inspection and other value-added services are additional lines. Confirm currency and unit because some charges apply per order, item or piece.",
      "Keep the expected amount and final order breakdown side by side. If the service type changes after staff review, pause and decide whether the added cost is justified. The goal is not to force an unusual request into the free workflow; it is to understand the service actually required before money is committed."),
    s("Plan for third-party product and seller risk",
      "Superbuy’s shopping-agent pages state that products come from third-party platforms and that the agent is not responsible for all product risks or legal consequences. Manual submission does not transform an unverified seller or restricted item into a guaranteed purchase. Review seller information, listing consistency, return limits and international mailing restrictions before asking an agent to proceed.",
      "Second-hand, customised, pre-sale and hard-to-verify products deserve a stricter risk note. Record what can be returned, what cannot be inspected, expected seller dispatch time and whether missing the release window would change the decision. If a purchase is non-returnable, the brief and warehouse evidence plan should be more precise, not less."),
    s("Define warehouse checks before the item arrives",
      "Expert Service solves the ordering input, not every quality question. Add a QC plan to the spreadsheet while the request is still fresh. Identify the model code, option label, quantity, visible custom text, included components and one measurement or angle that would change acceptance. Standard photos may not show the decision-critical detail.",
      "After warehouse receipt, compare the received item with the saved manual brief and agent confirmation. Use a focused detailed photo or re-inspection only when it can resolve a specific uncertainty. Do not claim that the service proves authenticity, internal performance, material composition or long-term durability."),
    s("Manage messages as a decision log",
      "Keep questions short and numbered. When the agent replies, record the answer beside the corresponding requirement and mark unresolved items. Avoid opening several threads with slightly different instructions. A single dated decision log makes it easier to see whether the seller confirmed the correct version and whether a price or dispatch change needs approval.",
      "If the request cannot be purchased, preserve the reason rather than immediately submitting the same incomplete information again. The result may reveal a restricted platform, unavailable option, minimum order, non-returnable condition or price change. Update the brief before a new attempt."),
    s("A reliable Expert Service workflow",
      "Start with a current product page and exact purchase specification. Try the standard supported flow first when appropriate; use manual expert submission when the page cannot be resolved or the order genuinely needs staff handling. Confirm the service category, all cost lines, seller response and after-sales limits before authorising purchase.",
      "Then track seller dispatch, inspect warehouse evidence against the saved brief, close any discrepancy promptly and move only accepted items into parcel planning. This workflow targets the search intent behind ‘Superbuy expert service’ while keeping the important distinction clear: staff assistance improves communication and order handling, but the buyer still owns the product choice, risk review and final decision."),
    s("Handle minimum orders, substitutions and seller replies",
      "Marketplaces such as 1688 may show minimum quantities or tiered prices. A manual request should state the acceptable quantity and whether a higher minimum cancels the order. For out-of-stock variations, say whether no substitution is allowed or list one exact fallback. Never write ‘similar is fine’ when size, material or model matters.",
      "Translate a seller reply into a decision record: confirmed option, revised price, dispatch estimate, return condition and unresolved point. Approve only after all material changes are visible together. If the seller bundles accessories or requires a deposit, ask how the order and after-sales status will be recorded before continuing."),
    s("Close the request with a warehouse-to-parcel handoff",
      "Once the item is stocked, attach the original brief to the warehouse decision. Confirm the option, quantity and visible custom details, note any aspect that photography cannot prove, and resolve anomalies within the available account process. The final warehouse status should explain why the item is accepted, not merely state that photos exist.",
      "Then move product cost and service fees into the completed-order record and send only parcel-relevant data—weight, dimensions, restrictions, packaging need and value—to shipping planning. This clean handoff prevents an expert ordering request from becoming a vague promise about international delivery."),
  ],

  "superbuy-fees": [
    s("Read Superbuy fees in two stages",
      "The clearest way to understand Superbuy fees is to separate the shopping stage from the international parcel stage. The current official fee structure groups product price, Chinese domestic delivery and any purchasing service fee in stage one. Stage two begins after warehouse arrival and covers international shipping based on the final parcel, selected line and destination. Optional value-added services can appear in either decision process.",
      "A single ‘total cost’ column hides when and why money is charged. Create separate fields for product, domestic delivery, purchasing service, warehouse services, international freight, insurance, storage and destination import costs. Record currency and date. The result is a budget that can be updated as better evidence becomes available."),
    s("Standard purchasing can be free without the order being free",
      "Superbuy currently lists standard purchasing service for mainstream platforms such as Taobao, Tmall, JD.com and 1688 as having no purchasing service fee. The product price and any seller domestic delivery still remain. Payment-provider or currency-conversion effects may also change what reaches a card statement, even though they are not an added percentage on the product price from standard purchasing.",
      "Use precise wording in the sheet: ‘standard purchasing service fee shown as zero’ is accurate for a qualifying order at that time. ‘No fees’ is not. Check the order breakdown because platform, seller, item and requested handling determine which service category applies."),
    s("Special purchasing categories use different rules",
      "The current official fee table lists separate treatment for second-hand platforms, other unlisted purchasing services and Shipping Expert orders. Some use a flat amount; others use a percentage with a minimum and maximum. These published figures can change, so the live service page and order confirmation should be checked immediately before payment.",
      "Record the source platform and service category next to the charge. If staff reclassify the request because of seller communication, pre-sale handling or an unsupported marketplace, compare the updated fee before approving it. A product URL alone is not enough to predict the correct purchasing category."),
    s("Optional services are priced by different units",
      "Superbuy lists value-added services such as detailed photos, re-inspection, label removal, power-on inspection, packaging changes and reinforcement. The displayed unit can be per piece, item, order or package, and several services have their own scope limits. Multiplying every service by product quantity without checking the unit can produce a bad estimate.",
      "Choose a service only when it answers a defined risk. A detailed photo may resolve one missing measurement; bubble cushioning may address impact risk; package removal may reduce volume but change protection. Save the service name, current price, unit and reason. This prevents optional tools from becoming an automatic bundle."),
    s("Storage fees begin after the free window",
      "The current fee page states that items receive 90 days of free storage after warehouse arrival. It then lists a daily per-item storage charge, a standard maximum period of 180 days and an extension service that should be purchased in advance when needed. The account’s live dates and terms take priority over a copied article.",
      "Track each item’s warehouse arrival, free-storage end and planned parcel date. An extension of the maximum period does not necessarily erase daily storage charges after the free period; the current fee description distinguishes those concepts. Resolve QC and return questions early so storage is used for consolidation rather than indecision."),
    s("International freight is not just a flat price per kilogram",
      "The official fee structure describes an initial-weight fee, additional-weight fee and possible customs, fuel or operation charges depending on the line. The system calculation also depends on destination and final parcel data. Volumetric weight, billing increments, minimum charges and restrictions can make two parcels with the same actual weight cost differently.",
      "Save the exact line, actual weight, dimensions, chargeable weight and quote date. Compare eligible routes on the same inputs. A social-media ‘rate per kilo’ without its first-weight rule, divisor, destination and date should not be used as a current budget."),
    s("The shipping deposit can be reconciled later",
      "Superbuy explains that the parcel fee is charged upfront from an estimated weight, selected route and destination, while the logistics provider’s verified size and weight determine the final charge. An overpayment may be returned to the account and an underpayment may be collected. Keep the original deposit instead of replacing it with the final number.",
      "When reconciling, compare packaging, weight, dimensions, route and any service added after the estimate. A difference is evidence to improve the next scenario. It should not automatically be described as a hidden fee, nor should one refund be promised on every parcel."),
    s("Keep destination taxes outside platform service fees",
      "Import VAT, customs duty, excise charges and courier handling come from destination rules and parcel assessment. Superbuy’s fee page says customs charges based on product category and declared value are borne by the recipient. A route may describe a tax-handling arrangement, but only its current terms explain the scope.",
      "Add a customs reserve using the receiving country’s official guidance. Do not mix that reserve into the platform purchasing fee, and do not advertise guaranteed tax-free delivery. Accurate declarations and current product restrictions are part of the parcel decision."),
    s("Audit the order and parcel breakdown",
      "At stage one, check product price, quantity, domestic delivery, service category, optional services and payment currency. At warehouse stage, add storage dates and any evidence service. At parcel stage, verify group contents, packaging, insurance, line, chargeable weight and deposit. After dispatch, record the final adjustment and import assessment.",
      "This staged audit makes fees explainable. It also supports better SEO than a table of copied prices because readers can apply the method after rates change. Current official pages and the account breakdown remain the source of truth."),
    s("Account for refunds, balances and timing",
      "A returned product, cancelled purchase or shipping adjustment may be credited to the platform account rather than the original payment method immediately. Record the event date, amount, currency, destination balance and any separate withdrawal or payment-provider step. Do not subtract an expected refund from the budget before it appears.",
      "Timing matters because another order can use an account balance while a card statement still shows the original payment. A simple ledger with charge, credit and final destination prevents double counting and makes a support enquiry specific."),
    s("Compare cost per decision, not only cost per item",
      "A low-value product can justify a paid photo when one visible measurement prevents an expensive international mistake. A protective service can be reasonable for a fragile high-value item and wasteful for soft clothing. Compare the service price with the risk it addresses, the return options and the freight that would be lost after shipment.",
      "This decision-based view also discourages selecting every add-on. Define the problem first, choose the smallest service that can resolve it, and verify the current unit price. Preserve the outcome so future choices use evidence instead of habit."),
    s("Monthly fee review for an active spreadsheet",
      "For frequently used sheets, review official fee categories monthly and immediately before any unusual purchase. Flag copied rates as expired rather than silently replacing them. Update service name, unit, date and official basis; keep old parcel records unchanged because they describe historical transactions.",
      "The resulting sheet answers two different questions cleanly: what did a past order cost, and what does the platform currently display for a new decision? Mixing those questions is the main reason fee guides become misleading."),
  ],

  "why-superbuy-shipping-estimate-changes": [
    s("An estimate changes when its inputs become real",
      "A Superbuy shipping estimate made before warehouse arrival relies on assumptions about weight, dimensions, packaging, route and item eligibility. After goods arrive, the warehouse can record better product data. After consolidation, there is a real outer carton. Finally, the logistics provider verifies size and weight. A change between these stages is expected whenever the inputs differ.",
      "Store each stage as a separate record: research estimate, warehouse scenario, parcel deposit and final settlement. Include date, destination, line, weight, dimensions and packaging. Overwriting the first number removes the evidence needed to explain the difference."),
    s("Product weight is not packed parcel weight",
      "A seller’s product weight may exclude retail packaging, accessories, protective material and the export carton. It may also be approximate. Conversely, removing unnecessary packaging can make the final parcel lighter. The parcel contains the sum of accepted items plus all material required to send them safely.",
      "Compare warehouse item records with the packed parcel record. If the difference matters, list the box, cushioning and retained packaging instead of assuming the scale is wrong. Build a small packaging allowance into early estimates, but replace it with measured data when available."),
    s("Dimensions can matter more than the scale",
      "Light, bulky parcels can be charged by volumetric weight. The Superbuy estimator gives a common air-cargo example of length × width × height divided by 6,000, but line-specific rules can differ. A few centimetres added to each side of a carton can materially increase cubic volume.",
      "Record all three outside dimensions and the applicable divisor. Check whether the line rounds dimensions or weight into billing increments. If a parcel changes carton or gains reinforcement, recalculate rather than carrying forward the earlier chargeable weight."),
    s("Packaging requests change the physical parcel",
      "Package removal, simple packaging and vacuum compression can reduce weight or volume for suitable goods. Bubble cushioning, corner protection, moisture barriers and stronger boxes can increase them. These services solve different risks; none should be selected only to chase the lowest displayed estimate.",
      "Write the purpose next to each request. Soft clothing may tolerate compression, while a collectible box or fragile item may need space and protection. The correct comparison includes both cost and acceptable damage risk."),
    s("Consolidation can improve or worsen the quote",
      "Combining orders may reduce duplicate base charges, but a larger carton can cross a weight band, become volumetric or exceed a route limit. One restricted item can also remove otherwise attractive delivery lines from the whole group. Free consolidation does not mean every consolidated configuration is cheapest.",
      "Test the complete group and at least one sensible split. Compare eligible lines, total freight, insurance and expected customs treatment. Save the scenario chosen and the reason, then update it if an item is removed or returned."),
    s("Route selection changes the calculation rules",
      "Delivery lines can use different first-weight charges, additional increments, volumetric divisors, limits and surcharges. Switching from an early generic estimate to an eligible live line can therefore change the price even if the parcel measurements stay constant. Availability can also change with destination and carrier conditions.",
      "Compare like with like: same parcel, same destination and same date. Open line details before deciding. A cheaper route may not accept the item attributes or may have different tracking and compensation terms."),
    s("The deposit is provisional",
      "The current Superbuy guide says the international shipping deposit is based on estimated weight, selected method and destination. The final shipping fee uses size and weight verified by the shipping company. The difference is reconciled after shipment through the account according to the current fee process.",
      "Preserve both values and the adjustment direction. Do not promise that every estimate will fall or that every difference will be refunded. The final verified data may be lower or higher than the deposit assumptions."),
    s("Currency and import charges create separate changes",
      "A card total can change because the exchange rate or payment conversion differs, even when the yuan freight charge is unchanged. Destination VAT, duty and courier handling can also be collected separately. These should not be described as changes to the warehouse shipping estimate.",
      "Use separate fields for quoted freight, paid freight, currency conversion and import assessment. That separation makes support questions clearer and prevents a customs bill from being mislabelled as a hidden platform shipping fee."),
    s("Diagnose a large difference with evidence",
      "Compare estimate date, destination, parcel contents, actual weight, dimensions, chargeable weight, divisor, billing increment, packaging services and selected line. Look for an item added late, retained retail box, reinforcement, restricted attribute or route change. Save screenshots of the quote and parcel record when the gap is material.",
      "If the numbers still do not reconcile, contact support with one parcel number and the saved inputs. A specific evidence bundle is more actionable than saying shipping became expensive."),
    s("Improve the next estimate",
      "After delivery, record final freight, adjustment, carton measurements, observed transit and packaging outcome. Note which early assumption caused the largest error. Use that result as a starting range for similar items, but verify current line rules again.",
      "A reliable shipping sheet learns progressively. It does not hide changed estimates; it explains which input changed and keeps the current quote tied to a real parcel."),
    s("Distinguish a normal revision from a problem",
      "A normal revision has traceable evidence: new measured dimensions, a different carton, added protection, a route rule or carrier verification. A potential problem is a material difference that remains unexplained after the parcel record and fee breakdown are compared. Classify the result before contacting support.",
      "For a potential problem, provide parcel number, quote date, selected line, deposit, final charge, measured weight, dimensions and screenshots. Avoid comparing with another user’s parcel unless contents, destination, date and calculation rules are genuinely the same. Specific evidence gives support a testable question."),
    s("Set a budget trigger before buying",
      "Before the product order, decide the maximum shipping range that would still make the purchase worthwhile. Use conservative weight and volume assumptions and include a separate import reserve. If the warehouse scenario exceeds that trigger, review return eligibility, item grouping and packaging options before adding more goods.",
      "A trigger turns the estimate into a decision tool. Without one, people often keep consolidating because earlier product spending feels irreversible. The sheet should make the current parcel economics visible before the international charge is paid."),
    s("Use scenario names and version dates",
      "Name scenarios by contents and purpose, such as clothing-only compact, shoes with boxes, or fragile split. Add a creation date and mark one as the current candidate. When contents or packaging change, duplicate the row and update inputs rather than editing the old result.",
      "Versioning makes a rising estimate understandable. It also prevents a screenshot from an abandoned configuration being compared with the final parcel. The most recent scenario is not automatically best; it is simply the one based on the latest stated assumptions."),
    s("Final reconciliation checklist",
      "After dispatch, compare the research estimate, warehouse scenario, deposit and final settlement in one view. Attribute each difference to contents, actual weight, volumetric weight, packaging, route, billing unit or currency when evidence supports it. Leave unexplained amounts clearly marked instead of inventing a reason.",
      "Add the carrier-verified parcel data and account adjustment date. Then archive the scenario as historical. For the next parcel, copy only useful physical assumptions and reopen the current calculator and line terms. This closes the loop without treating a past price as a standing offer."),
  ],

  "superbuy-warehouse-storage": [
    s("Start the storage clock at warehouse arrival",
      "Superbuy’s current fee structure states that items receive 90 days of free storage after arrival. The useful date is the warehouse stock-in date for each item, not the day you first found or paid for it. Different orders can therefore have different deadlines even when they are intended for one parcel.",
      "Create fields for purchase date, seller dispatch, warehouse arrival, free-storage end and planned parcel date. Sort by the oldest warehouse item. This turns storage from a vague allowance into a visible schedule."),
    s("Use the free period for deliberate work",
      "The free window supports consolidation, but it should also include warehouse inspection, detailed evidence requests, seller communication and any eligible after-sales action. An item with an unresolved size or damage question is not ready merely because another purchase is still in transit.",
      "Set a personal decision deadline earlier than the official limit. Leave time for a new photo, support reply, possible return and parcel reconfiguration. The official account date remains controlling."),
    s("Understand fees after the free window",
      "The current official fee page lists a daily per-item charge after 90 free days and a standard maximum storage period of 180 days. Because rates can change, check the live service page and account before relying on copied values. The cost can accumulate across many separate items.",
      "Add a warning column rather than waiting for the final week. Use bands such as review now, parcel planned and extension decision. Do not erase overdue history; keep the actual date and fee evidence for later planning."),
    s("An extension changes the maximum period, not every charge",
      "Superbuy currently offers an Extend Storage Period service purchased in advance. Its description says the service extends the maximum storage period and that storage fees after the free period are still charged by day when the parcel is submitted. Treat extension cost and daily storage cost as separate lines.",
      "Before buying an extension, confirm eligible items, duration, current price, maximum extension and the new account deadline. Use it for a clear reason, such as waiting for a delayed pre-order, not as a substitute for deciding what to ship."),
    s("Consolidate by compatibility",
      "Superbuy says eligible stored items can be consolidated without a consolidation fee and may reduce international shipping cost. Compatibility matters more than simply putting everything into one box. Weight, dimensions, fragility, batteries, liquids, restricted attributes and original packaging can affect route eligibility.",
      "Create parcel groups and test at least one split. A small restricted item can narrow the route list for a large otherwise simple parcel. A bulky box can create volumetric weight. Document the chosen group and the reason."),
    s("Close QC decisions before parcel submission",
      "For each item, record identity, quantity, selected option, visible condition, measurement result and unresolved limitation. Use a clear final status: accept, request evidence, seek clarification, return if eligible, discard or hold. ‘Looks fine’ is not a reproducible decision.",
      "Prioritise new arrivals that may still have after-sales options, then older items nearing storage limits. The storage sheet should show both time pressure and evidence quality."),
    s("Plan packaging while items are still stored",
      "Package removal or compression may reduce volume, while reinforcement and cushioning may protect fragile goods. Decide which retail boxes must remain and which packaging can safely be changed. Save these preferences before submission so the parcel estimate uses a realistic configuration.",
      "Do not remove protective packaging only to lower a number. Record the trade-off between cost, damage risk and collector or resale value. Different groups may need different packaging strategies."),
    s("Handle delayed and pre-sale items separately",
      "A delayed seller dispatch can leave earlier purchases ageing in storage. Do not let one uncertain item silently control the whole parcel. Compare the cost and risk of waiting, extending storage or sending the ready group first.",
      "For pre-sales, record the expected seller date and a decision checkpoint. If the date changes, recalculate the oldest item’s storage position and shipping scenarios."),
    s("Use a weekly warehouse review",
      "Once a week, sort by oldest arrival, review new photos, close open questions, update seller delays and recalculate parcel groups. Check current line eligibility when a group becomes nearly ready. This small routine prevents deadline-driven decisions.",
      "Keep an archive of shipped, returned and discarded items. Historical storage duration and parcel outcomes improve future purchase timing without turning past rules into current facts."),
    s("A storage-to-parcel checklist",
      "Before submitting, confirm every item’s decision, the oldest date, any accrued fee, extension status, parcel group, packaging request, destination and route eligibility. Then compare actual and volumetric weight and review declaration information.",
      "The strongest storage plan uses the 90-day window as structured decision time. It neither rushes items into international shipping nor treats the warehouse as indefinite storage."),
    s("Create deadline buffers for after-sales work",
      "Storage and seller after-sales timelines are not the same. A product can have many warehouse days remaining while an eligible return or exchange window is much shorter. Record the notice date and the account’s current after-sales deadline separately. Inspect new arrivals promptly even when the planned parcel is weeks away.",
      "Use a buffer for staff messages, seller approval and domestic return transit. If eligibility is uncertain, ask through the order record immediately. Waiting for other items should never silently consume the time available to resolve a visible problem."),
    s("Track multi-item orders at item level",
      "One domestic order can contain several pieces that arrive or pass inspection differently. Storage fees and extension descriptions may use per-item or per-order units, while parcel decisions can split products. Give every stored piece an item identifier linked to its original order.",
      "Record quantity, option, stock-in status, QC decision and parcel group for each item. This prevents one returned piece from making the whole order appear unresolved and helps calculate storage exposure accurately."),
    s("Plan abandonment and disposal risk explicitly",
      "The current fee page states that items without parcel submission or feedback after the maximum period may be treated as abandoned and disposed of. Do not rely on an unmonitored account alert as the only safeguard. Put the maximum date in a calendar and review it well in advance.",
      "If an item is no longer worth shipping, make a deliberate account decision using current options rather than letting the deadline decide by accident. Preserve confirmation of any return, disposal or extension request."),
    s("Warehouse dashboard columns",
      "A compact dashboard needs item ID, description, option, arrival date, free-storage end, maximum date, after-sales deadline, QC status, weight, dimensions, restriction flag, packaging preference and parcel group. Add an owner and next-action date if several people share the sheet.",
      "Use conditional highlighting for deadlines, but keep the underlying date readable. The dashboard should point to the account record, not duplicate changing platform status as if it were live. Review and date every manual update."),
    s("Final weekly control before the oldest deadline",
      "As the oldest item approaches its planned cutoff, freeze new discretionary purchases and decide the ready parcel. Recheck every open QC point, extension request and route restriction. Compare the cost of waiting with the cost of sending the accepted group now, including possible storage charges and another parcel’s base fee.",
      "Document the decision and next review date. A deliberate hold may be reasonable, but it should name the delayed item, expected arrival and financial limit. This prevents indefinite consolidation from turning a generous storage window into an avoidable loss."),
  ],

  "superbuy-shipping-to-uk": [
    s("Plan a UK parcel with two rule sets",
      "Superbuy shipping to the UK combines the platform’s warehouse and delivery process with UK customs and tax rules. The first determines parcel composition, chargeable weight and eligible lines. The second determines whether VAT, Customs Duty, Excise Duty or handling charges may be collected. Keep these rule sets separate and verify both immediately before submission.",
      "This guide is planning information, not tax advice. HMRC rules and delivery-line terms can change. Save the official page title and access date with every threshold used."),
    s("Distinguish Great Britain from Northern Ireland",
      "HMRC’s guidance distinguishes Great Britain—England, Scotland and Wales—from Northern Ireland in some import situations. A route or customs explanation that is correct for one destination may not describe the other. Enter the full destination early and use the applicable official guidance.",
      "Do not shorten the country field to ‘UK’ inside the research notes. Record GB or Northern Ireland, postcode, product type and origin assumptions so the customs check can be reproduced."),
    s("Understand VAT on goods sent from abroad",
      "Current GOV.UK guidance says VAT applies to goods sent from outside the UK to Great Britain, subject to specific exceptions such as qualifying low-value gifts. For bought goods worth £135 or less in total that are not excise goods, VAT is generally included when purchased under the applicable sales rules. For goods above £135, import VAT is normally paid to the delivery company before receipt or collection.",
      "A shopping-agent workflow can be more complex than a simple direct retail sale, so do not assume where VAT was collected. Check the order, route terms and courier notice. Keep a VAT reserve until the evidence shows the actual treatment."),
    s("Use the £135 threshold at consignment level",
      "GOV.UK states that Customs Duty in Great Britain can apply to goods from outside the UK when they are excise goods or worth more than £135. For non-excise goods above that value, the duty rate depends on the type and origin and should be checked in the UK Trade Tariff. The threshold applies to the consignment, not a casual per-item split.",
      "Consolidation can therefore change both shipping efficiency and the customs scenario. Compare one combined parcel with a sensible split, but never undervalue goods or create misleading descriptions to target a threshold."),
    s("Remember what enters the tax base",
      "HMRC’s consumer guidance explains that when VAT is paid to the delivery company, the calculation can include the goods, postage, packaging, insurance and any duty owed. Customs Duty, when charged, can also be calculated on the goods plus postage, packaging and insurance. Use the live guidance for the exact parcel.",
      "Keep product value, international freight, insurance and expected duty in separate columns. Then build the VAT scenario from the components HMRC requires. This avoids applying a percentage only to the product subtotal when the rule uses a broader base."),
    s("A purchase is not automatically a gift",
      "GOV.UK gift relief is limited to genuine occasional gifts sent from one private person outside the UK to another private person, without direct or indirect payment by the UK recipient. Buying goods for yourself, or buying a product as a present, does not automatically qualify the shipment as a customs gift.",
      "Use an honest commercial description and value. If a parcel is a genuine gift, consult the separate HMRC gift guidance, including the current £39 VAT relief threshold and other conditions."),
    s("Build the parcel estimate from chargeable weight",
      "Before warehouse arrival, test a weight and size range in the Superbuy calculator. After arrival, replace assumptions with item data and compare actual with volumetric weight. The general Superbuy estimator gives a common air-cargo example using cubic centimetres divided by 6,000, but the selected line may publish a different rule.",
      "Compare UK-eligible lines on the same contents, destination, dimensions and date. Open the details for restrictions, declared-value rules, tracking, insurance and tax handling. Do not choose from the headline price alone."),
    s("Consolidate with UK value and route effects in view",
      "Free consolidation may lower repeated shipping charges, yet a combined consignment can exceed a customs value threshold or become volumetric. One restricted product can also reduce available lines. Test the combined group and a split by volume, fragility or restriction.",
      "Record why you chose the group. The best result balances total freight, protection, line eligibility and a compliant customs budget; it is not always the fewest parcels."),
    s("Prepare an accurate declaration and evidence file",
      "List the real goods in plain language, with quantity and value. Keep order confirmations, payment records, product descriptions, parcel number and freight evidence. Accurate contact details matter because Royal Mail, Parcelforce or a courier may request tax, duty, documents or a handling payment before delivery.",
      "Monitor tracking and respond within the notice period. GOV.UK notes that a parcel can be held and returned when a required bill is not paid. Never depend on a route nickname as proof that no action will be needed."),
    s("Use the UK Trade Tariff for product-specific duty",
      "When the parcel is above the relevant threshold or contains a special product, use the official UK Trade Tariff to identify classification, duty rate, restrictions and possible relief. A broad article cannot select the code for every garment, electronic item or accessory.",
      "If classification or origin is genuinely uncertain and the cost matters, seek specialist advice. Mark the sheet as unresolved until the official code and basis are established."),
    s("Final UK submission check",
      "Confirm GB or Northern Ireland destination, parcel contents, actual and volumetric weight, selected line, insurance, honest description, consignment value and current HMRC rules. Keep a reserve for VAT, duty and courier handling rather than promising tax-free delivery.",
      "After receipt, record the final freight, any account adjustment, VAT or duty assessment, handling charge and observed transit. Recheck official guidance for the next parcel. A useful UK shipping spreadsheet is dated, evidence-led and explicit about what remains uncertain."),
    s("Allow for courier handling and payment timing",
      "Royal Mail, Parcelforce or another courier may contact the recipient when VAT, duty or delivery charges are due. The payment request can include a carrier handling component separate from tax. Keep the recipient name, address, phone and email accurate and monitor tracking so the notice is not missed.",
      "Budget a separate handling reserve because it may not appear in the Superbuy freight quote. Save the issuer and payment receipt. If a message looks suspicious, verify it through the courier’s official tracking or contact channel before paying."),
    s("Returns do not automatically reverse every charge",
      "If goods are returned or an assessment appears too high, GOV.UK provides processes for claiming eligible VAT or Customs Duty refunds. The correct form or route can depend on the carrier. Shipping, handling and platform costs may follow different refund rules.",
      "Keep the import assessment, proof of return, courier, dates and order evidence. Do not assume a product refund automatically recovers border charges. Follow the current official procedure and record the final outcome separately."),
    s("UK parcel worksheet fields",
      "Use columns for GB or Northern Ireland, postcode, product description, quantity, origin, item value, freight, insurance, consignment value, possible tariff code, VAT basis, duty scenario, courier handling reserve and source date. Link each assumption to the account record or named official guidance.",
      "Add status values for unverified, checked and assessed. A threshold copied into the sheet is not enough; show whether the actual consignment and product type meet its conditions. Immediately before payment, recheck HMRC guidance and the chosen line. After delivery, replace the scenario with the real assessment while preserving the original estimate."),
  ],
};

export const articleMetaData: Record<string, { title: string; description: string }> = Object.fromEntries(
  newArticleRows.map(([slug, title, description]) => [slug, { title, description }]),
);
